local H=game:GetService("HttpService") local was=H.HttpEnabled H.HttpEnabled=true local ok,body=pcall(function() return H:GetAsync("https://raw.githubusercontent.com/voxmac/splashfront/main/game/SF_Bundle.json?t="..os.time(),true) end) H.HttpEnabled=was assert(ok,body) local B=H:JSONDecode(body) local RS=game:GetService("ReplicatedStorage") local SSS=game:GetService("ServerScriptService") local SPS=game:GetService("StarterPlayer").StarterPlayerScripts local function put(list,parent) for _,e in ipairs(list) do local o=parent:FindFirstChild(e.Name) if o and o.ClassName~=e.Class then o:Destroy() o=nil end if not o then o=Instance.new(e.Class) o.Name=e.Name o.Parent=parent end o.Source=e.Source end end local sh=RS:FindFirstChild("Shared") or Instance.new("Folder",RS) sh.Name="Shared" put(B.Shared,sh) put(B.Server,SSS) put(B.Client,SPS) local cfg=require(sh.Config:Clone()) print("SF_UPDATE OK","shared",#B.Shared,"server",#B.Server,"client",#B.Client,"build",cfg.Build)
